using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
[InitializeOnLoad]public static class Scene05HomecomingFinalize{static Scene05HomecomingFinalize(){EditorApplication.delayCall+=Run;}static void Run(){if(EditorApplication.isPlaying||File.Exists("Temp/scene05-final.done")||!File.Exists("Temp/scene05-build.done"))return;try{var story=UnityEngine.Object.FindObjectOfType<Scene05HomecomingStory>();if(!story)return;story.Sample(0);story.doorway=new Vector3(1.35f,.15f,-4.5f);story.outside=new Vector3(1.35f,.15f,-5.7f);story.door.position=new Vector3(.86f,.15f,-4.5f);var panel=story.door.Find("Front door");panel.localPosition=new Vector3(.49f,.855f,0);panel.localScale=new Vector3(.98f,1.71f,.045f);var handle=story.door.Find("Door handle");handle.localPosition=new Vector3(.85f,.85f,.055f);
var row=UnityEngine.Object.FindObjectsOfType<MeshFilter>(true).First(f=>f.name=="rowhouse_1960");var mesh=UnityEngine.Object.Instantiate(row.sharedMesh);mesh.name="Scene05 Rowhouse with operable front door";var v=mesh.vertices;var tri=mesh.GetTriangles(9);var keep=new System.Collections.Generic.List<int>();int removed=0;for(int i=0;i<tri.Length;i+=3){var points=new[]{tri[i],tri[i+1],tri[i+2]}.Select(k=>row.transform.TransformPoint(v[k])).ToArray();if(points.All(p=>p.z< -4.49f&&p.y<1.9f&&p.x>.8f)&&points.Any(p=>p.z< -4.6f)){removed++;continue;}keep.AddRange(new[]{tri[i],tri[i+1],tri[i+2]});}mesh.SetTriangles(keep,9);AssetDatabase.CreateAsset(mesh,"Assets/Scene05HomecomingAnimation/Rowhouse_OperableDoor.asset");row.sharedMesh=mesh;row.GetComponent<MeshCollider>().sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(row);PrefabUtility.RecordPrefabInstancePropertyModifications(row.GetComponent<MeshCollider>());
var floor=new GameObject("Scene05 exploration floor safety");floor.transform.SetParent(story.transform,false);floor.transform.position=new Vector3(0,.10f,-2);var box=floor.AddComponent<BoxCollider>();box.size=new Vector3(4.7f,.10f,5.0f);
var fill=new GameObject("Scene05 soft face fill",typeof(Light));fill.transform.SetParent(story.transform,false);fill.transform.position=new Vector3(-.72f,2.1f,-2.4f);var light=fill.GetComponent<Light>();light.type=LightType.Point;light.range=4;light.intensity=.5f;light.color=new Color(1,.88f,.74f);
story.director.time=0;story.director.Evaluate();story.Sample(0);EditorUtility.SetDirty(story);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(story.gameObject.scene);EditorSceneManager.SaveScene(story.gameObject.scene);File.WriteAllText("Temp/scene05-final.done","Removed baked front door triangles="+removed); }catch(Exception e){File.WriteAllText("Temp/scene05-final.error",e.ToString());Debug.LogException(e);}}}
